function parseCount(v){if(typeof v==='number')return Math.max(0,Math.round(v));if(!v)return 0;var raw=String(v).replace(/,/g,'').replace(/[+\s]/g,'').trim();var m=raw.match(/(\d+(?:\.\d+)?)/);if(!m)return 0;var n=parseFloat(m[1]);if(raw.indexOf('亿')>=0)return Math.round(n*100000000);if(raw.indexOf('万')>=0||/w$/i.test(raw))return Math.round(n*10000);if(raw.indexOf('千')>=0||/k$/i.test(raw))return Math.round(n*1000);return Math.round(n);}

class VideohaoScraper {
  constructor(){this.browser=null;this.activeFetches=new Set();this.logFile=require('path').join(__dirname,'..','logs','videohao-sync.log');}

  async init(){if(this.browser)return;var ep=this._findChromePath();var p=require('puppeteer-extra');this.browser=await p.launch({headless:true,executablePath:ep||undefined,args:['--no-sandbox','--disable-setuid-sandbox','--disable-blink-features=AutomationControlled','--disable-infobars','--disable-gpu','--disable-dev-shm-usage']});}

  async close(){if(this.browser){await this.browser.close().catch(function(){});this.browser=null;}}

  async fetchProfileAndPosts(ai,as,mp,sd,ed,op){var ak=ai||'current';if(this.activeFetches.has(ak))return{success:false,busy:true};this.activeFetches.add(ak);var pg=null;try{await this.init();pg=await this.browser.newPage();await pg.setViewport({width:1366,height:900});await pg.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36');var na=this._normalizeAuthState(as);await this._applyAuthState(pg,na);var cposts=[];var cprof=null;var tu=op&&op.targetUrl?String(op.targetUrl).trim():'';pg.on('response',(function(r){try{var u=r.url();var ct=r.headers()['content-type']||'';if(!u.includes('channels.weixin.qq.com')||!ct.includes('application/json'))return;r.json().then(function(d){var p=this._extractProfileFromJson(d);if(p)cprof=cprof||p;var ps=this._extractPostsFromJson(d);if(ps.length)cposts.push.apply(cposts,ps);}.bind(this)).catch(function(){});}catch(e){}}).bind(this));try{await pg.goto(tu||'https://channels.weixin.qq.com/platform',{waitUntil:'networkidle0',timeout:30000})}catch(e){}await this._wait(5000);try{await pg.screenshot({path:'D:\\Coding\\social-media-monitor\\server\\debug_vh.png',fullPage:true})}catch(e){}for(var i=0;i<6;i++){try{await pg.evaluate(function(){window.scrollBy(0,document.body.scrollHeight)})}catch(e){}await this._wait(1600);if(cposts.length>=mp)break}if(cposts.length===0){try{var domPosts=await pg.evaluate(function(){var items=document.querySelectorAll('[class*=video],[class*=post],[class*=feed],[class*=card]');var result=[];items.forEach(function(el){var text=el.textContent||'';if(text.length>10)result.push({title:text.substring(0,100)});});return result;});if(domPosts.length>0){cposts.push.apply(cposts,domPosts);}}catch(e){}}var all=this._dedupePosts(cposts).map(function(p){return this._normalizePost(p)}.bind(this)).filter(function(p){return p&&p.video_id});if(all.length===0&&tu){var pageState=await pg.evaluate(function(){return{url:location.href,title:document.title,bodyLen:document.body&&document.body.innerText.length||0,text:(document.body&&document.body.innerText||'').substring(0,200)}}).catch(function(){return{}});console.log('[VH] Page state:',JSON.stringify(pageState));}await pg.close().catch(function(){});this.activeFetches.delete(ak);return{success:true,data:{posts:all,profile:cprof}};}catch(e){if(pg)await pg.close().catch(function(){});this.activeFetches.delete(ak);return{success:false,error:e.message};}}

  async searchAccounts(kw,as,ps){var query=String(kw||'').trim();if(!query)return{success:false,error:'请输入视频号名称或ID'};var pg=null;try{await this.init();pg=await this.browser.newPage();await pg.setViewport({width:1366,height:900});await pg.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36');var auth=this._normalizeAuthState(as);await this._applyAuthState(pg,auth);await pg.goto('https://channels.weixin.qq.com/platform/post/create',{waitUntil:'domcontentloaded',timeout:45000}).catch(function(){});await this._wait(2500);if(await this._isLoginRequired(pg)){await pg.close().catch(function(){});return{success:false,cookieExpired:true,error:'视频号 Cookie 已失效，请重新扫码登录'};}var response=await pg.evaluate(async function(args){var makeId=function(){return window.crypto&&typeof window.crypto.randomUUID==='function'?window.crypto.randomUUID():Date.now()+'-'+Math.random().toString(16).slice(2);};var apiUrl='/cgi-bin/mmfinderassistant-bin/helper/helper_search_finder_account?_aid='+encodeURIComponent(makeId())+'&_rid='+encodeURIComponent(makeId())+'&_pageUrl='+encodeURIComponent(location.href);var resp=await fetch(apiUrl,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({pageSize:args.pageSize,currentPage:1,offset:0,query:args.query})});var text=await resp.text();try{return{status:resp.status,data:JSON.parse(text)};}catch(e){return{status:resp.status,text:text};}},{query:query,pageSize:Math.min(Math.max(Number(ps)||10,1),20)});await pg.close().catch(function(){});if(!response||response.status<200||response.status>=300)return{success:false,error:'视频号搜索接口异常：'+(response&&response.status||'unknown')};if(response.data&&response.data.errCode!==0)return{success:false,error:response.data.errMsg||response.data.message||'视频号搜索失败'};var list=response.data&&response.data.data&&Array.isArray(response.data.data.list)?response.data.data.list:[];return{success:true,data:list.map(this._parseSearchAccountItem.bind(this)).filter(Boolean),total:Number(response.data&&response.data.data&&response.data.data.totalCount||list.length||0)};}catch(e){if(pg)await pg.close().catch(function(){});return{success:false,error:e.message};}}

  _parseSearchAccountItem(it){if(!it||typeof it!=='object')return null;var uid=it.username||it.finderUsername||it.uniqId||it.uniqueId;if(!uid)return null;return{unique_id:String(uid).trim(),sec_uid:String(uid).trim(),nickname:it.nickName||it.nickname||it.name||'',avatar:it.headImgUrl||it.avatarUrl||it.avatar||it.iconUrl||'',signature:it.signature||it.description||it.desc||it.authCompanyName||'',verified:it.authImgUrl?1:0,auth_img_url:it.authImgUrl||'',auth_company_name:it.authCompanyName||'',follower_count:parseCount(it.fansCount||it.followerCount||it.followers),video_count:parseCount(it.feedCount||it.feedsCount||it.videoCount)};}

  _normalizePost(p){if(!p||!p.video_id)return null;return{video_id:String(p.video_id).trim(),title:String(p.title||p.description||'').trim(),description:String(p.description||p.title||'').trim(),cover_url:String(p.cover_url||'').trim(),video_url:String(p.video_url||'').trim(),duration:parseCount(p.duration),play_count:parseCount(p.play_count),like_count:parseCount(p.like_count),comment_count:parseCount(p.comment_count),share_count:parseCount(p.share_count),collect_count:parseCount(p.collect_count),published_at:this._formatTime(p.published_at||p.publish_time||p.createTime)};}

  _extractPostsFromJson(j){var r=[];var l=j&&(j.data&&j.data.list||j.list||j.data&&j.data.postList||j.postList);if(Array.isArray(l)){for(var i=0;i<l.length;i++){var p=this._parsePostListItem(l[i]);if(p)r.push(p);}}return r;}

  _parsePostListItem(it){if(!it)return null;var fid=it.feedId||it.objectId||it.exportId||it.id;if(!fid)return null;return{video_id:String(fid).trim(),title:String(it.title||it.desc||'').trim(),description:String(it.desc||it.title||'').trim(),cover_url:String(it.coverUrl||it.thumbUrl||'').trim(),video_url:String(it.url||it.videoUrl||'').trim(),duration:parseCount(it.duration||it.videoPlayLen),play_count:parseCount(it.playCount||it.readCount),like_count:parseCount(it.likeCount||it.likedCount),comment_count:parseCount(it.commentCount),share_count:parseCount(it.shareCount||it.forwardCount),collect_count:parseCount(it.collectCount||it.favoriteCount),published_at:this._formatTime(it.publishTime||it.createTime||it.timestamp)};}

  _extractProfileFromJson(d){var cs=[];this._walk(d,function(v){if(!v||typeof v!=='object')return;var uid=v.uniqId||v.uniq_id||v.finderUsername||v.finderUserName||v.finder_uniq_id||v.username;var nick=v.nickname||v.nickName||v.finderNickname||v.name;if(uid||nick)cs.push({unique_id:uid?String(uid).replace(/^@/,'').trim():'',sec_uid:v.finderUsername||null,nickname:nick||'',avatar:v.avatar||v.avatarUrl||v.headImgUrl||v.headimgurl||v.iconUrl||'',follower_count:parseCount(v.fansCount||v.followerCount||v.followers||v.fans_count),following_count:parseCount(v.followCount||v.followingCount||v.follow_count),like_count:parseCount(v.likeCount||v.likedCount||v.like_count),video_count:parseCount(v.feedsCount||v.feedCount||v.videoCount)});});return cs.length>0?cs[0]:null;}

  _walk(r,v,l){l=l||3000;var q=[r];var s=new WeakSet();var i=0;while(q.length&&i<l){var c=q.shift();i++;if(!c||typeof c!=='object')continue;if(s.has(c))continue;s.add(c);v(c);var vals=Array.isArray(c)?c:Object.values(c);for(var j=0;j<vals.length;j++){if(vals[j]&&typeof vals[j]==='object')q.push(vals[j]);}}}

  _findChromePath(){var pp=['C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe','C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe',process.env.LOCALAPPDATA+'\\Google\\Chrome\\Application\\chrome.exe'];for(var i=0;i<pp.length;i++){if(pp[i]&&require('fs').existsSync(pp[i]))return pp[i];}return null;}

  _normalizeAuthState(as){if(!as)return{cookies:[],localStorage:{},sessionStorage:{}};var p=as;if(typeof as==='string'){try{p=JSON.parse(as)}catch(e){p=[]}}if(Array.isArray(p))return{cookies:p,localStorage:{},sessionStorage:{}};return{cookies:Array.isArray(p.cookies)?p.cookies:[],localStorage:p.localStorage||{},sessionStorage:p.sessionStorage||{}};}

  async _applyAuthState(page,as){var c=(as.cookies||[]).map(function(c){return{name:c.name,value:c.value,domain:c.domain||'channels.weixin.qq.com',path:c.path||'/',httpOnly:!!c.httpOnly,secure:c.secure!==false,sameSite:c.sameSite||'None'};});if(c.length){await page.setCookie.apply(page,c);}if(as.localStorage){await page.evaluate(function(s){for(var k in s){try{localStorage.setItem(k,s[k])}catch(e){}}},as.localStorage);}}

  _isLoginRequired(page){return page.evaluate(function(){var t=document.body&&document.body.innerText||'';var u=location.href;if(u.indexOf('/login')>=0)return true;return t.indexOf('扫码')>=0||t.indexOf('微信扫码')>=0||t.indexOf('登录后使用')>=0;}).catch(function(){return true;});}

  _mergeProfile(){var r={};for(var i=0;i<arguments.length;i++){var p=arguments[i];if(!p)continue;for(var k in p){if(p[k]&&!r[k])r[k]=p[k];}}return r;}

  _formatTime(v){if(!v)return null;if(typeof v==='number'){var ms=v>100000000000?v:v*1000;return this._formatDate(new Date(ms));}return null;}

  _formatDate(d){if(!(d instanceof Date)||isNaN(d.getTime()))return null;return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')+':'+String(d.getSeconds()).padStart(2,'0');}

  _dedupePosts(posts){var map=new Map();(posts||[]).forEach(function(p){var id=String(p.video_id||p.id||'').trim();if(!id||map.has(id))return;map.set(id,p);});return Array.from(map.values());}

  _matchesAccount(expected,profile){if(!expected||!profile)return true;var c=[profile.unique_id,profile.sec_uid,profile.nickname];for(var i=0;i<c.length;i++){if(this._sameAccount(expected,c[i]))return true;}return false;}

  _sameAccount(a,b){a=String(a||'').replace(/^@/,'').trim();b=String(b||'').replace(/^@/,'').trim();return!a||!b||a===b;}

  _wait(ms){return new Promise(function(r){setTimeout(r,ms);});}
}
module.exports = VideohaoScraper;
